import React, { useMemo } from "react";
import {
  PieChart,
  Pie,
  Cell,
  Tooltip,
  BarChart,
  Bar,
  XAxis,
  YAxis,
  ResponsiveContainer
} from "recharts";

function InsightsPage({ transactions, alerts, insights, darkMode, goBack }) {

  // 🎨 COLORS (auto works with your UI)
  const COLORS = ["#4f6df5", "#22c55e", "#f59e0b", "#ef4444", "#8b5cf6"];

  // 📊 CATEGORY DATA
  const categoryData = useMemo(() => {
    let totals = {};

    transactions.forEach(t => {
      const cat = t.category || "Other";
      totals[cat] = (totals[cat] || 0) + Number(t.amount || 0);
    });

    return Object.entries(totals).map(([name, value]) => ({
      name,
      value
    }));
  }, [transactions]);

  // 🧠 AI SUMMARY (natural language)
  const aiSummary = useMemo(() => {
    if (!transactions.length) return "Upload a statement to see insights.";

    let total = transactions.reduce((sum, t) => sum + Number(t.amount || 0), 0);

    let top = categoryData.sort((a, b) => b.value - a.value)[0];

    let alertMsg = alerts.find(a => a.exceeded)
      ? "You have exceeded some budgets, which needs attention."
      : "Your spending is mostly within limits.";

    return `This month, your total spending was ₹${total.toFixed(0)}. 
The highest spending category was ${top?.name}, contributing significantly to your expenses. 
${alertMsg} Overall, your financial behavior shows ${insights.length > 3 ? "diverse spending patterns" : "controlled spending habits"}.`;
  }, [transactions, categoryData, alerts, insights]);

  return (
    <div className="container" style={{ marginTop: "20px" }}>

      {/* HEADER */}
      <div className="card">
        <h2>AI Financial Insights</h2>

        <button
          onClick={goBack}
          style={{
            marginTop: "10px",
            padding: "6px 12px",
            borderRadius: "6px",
            border: "none",
            background: "#4f6df5",
            color: "#fff",
            cursor: "pointer"
          }}
        >
          ← Back to Dashboard
        </button>
      </div>

      {/* AI SUMMARY */}
      <div className="card" style={{ marginTop: "20px" }}>
        <h3>AI Summary</h3>
        <p style={{ lineHeight: "1.6" }}>{aiSummary}</p>
      </div>

      {/* PIE CHART */}
      <div className="card" style={{ marginTop: "20px" }}>
        <h3>Spending Breakdown</h3>

        <div style={{ width: "100%", height: 300 }}>
          <ResponsiveContainer>
            <PieChart>
              <Pie
                data={categoryData}
                dataKey="value"
                nameKey="name"
                outerRadius={100}
                label
              >
                {categoryData.map((entry, index) => (
                  <Cell key={index} fill={COLORS[index % COLORS.length]} />
                ))}
              </Pie>
              <Tooltip />
            </PieChart>
          </ResponsiveContainer>
        </div>
      </div>

      {/* BAR CHART */}
      <div className="card" style={{ marginTop: "20px" }}>
        <h3>Category Spending</h3>

        <div style={{ width: "100%", height: 300 }}>
          <ResponsiveContainer>
            <BarChart data={categoryData}>
              <XAxis dataKey="name" />
              <YAxis />
              <Tooltip />
              <Bar dataKey="value" />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>

      {/* EXISTING INSIGHTS */}
      <div className="card" style={{ marginTop: "20px" }}>
        <h3>Detailed Insights</h3>

        {insights.length > 0 ? (
          insights.map((i, idx) => <p key={idx}>{i}</p>)
        ) : (
          <p>No insights available</p>
        )}
      </div>
    </div>
  );
}

export default InsightsPage;
